tasks.script:
node --input-type=module -e "
const REPO = 'shader-slang/slang';
const H = {
  Authorization: 'token ' + process.env.GH_TOKEN,
  Accept: 'application/vnd.github+json',
  'User-Agent': 'slang-ci-babysitter',
};
const api = async (p) => {
  const r = await fetch('https://api.github.com/repos/' + REPO + p, { headers: H });
  if (!r.ok) throw new Error('GitHub API ' + r.status + ' ' + r.statusText + ' for ' + p);
  return r.json();
};

try {
  const prs = await api('/pulls?state=open&per_page=50');
  if (!Array.isArray(prs)) {
    console.log(JSON.stringify({ wakeAgent: true, data: { error: 'unexpected /pulls response' } }));
    process.exit(0);
  }
  const nonDraft = prs.filter((p) => !p.draft);
  const openNums = new Set(nonDraft.map((p) => p.number));

  const sinceMs = Date.now() - 24 * 3600 * 1000;
  const FAIL = new Set(['failure', 'cancelled', 'timed_out', 'startup_failure']);
  const evicted = [];
  try {
    const runs = await api('/actions/runs?event=merge_group&per_page=50');
    const seen = new Set();
    for (const r of runs.workflow_runs || []) {
      if (!FAIL.has(r.conclusion)) continue;
      if (new Date(r.run_started_at || r.created_at).getTime() < sinceMs) continue;
      const m = /pr-(\d+)-/.exec(r.head_branch || '');
      if (!m) continue;
      const num = Number(m[1]);
      if (!openNums.has(num)) continue;
      if (seen.has(num)) continue;
      seen.add(num);
      evicted.push({
        number: num,
        mergeGroupRunId: r.id,
        workflow: r.name,
        headBranch: r.head_branch,
        conclusion: r.conclusion,
        runStartedAt: r.run_started_at,
        runUrl: r.html_url,
      });
    }
  } catch (e) {
    evicted.push({ error: e.message });
  }

  console.log(JSON.stringify({
    wakeAgent: nonDraft.length > 0,
    data: {
      prCount: nonDraft.length,
      prs: nonDraft.map((p) => ({ number: p.number, title: p.title })).slice(0, 20),
      evicted,
    },
  }));
} catch (e) {
  console.log(JSON.stringify({ wakeAgent: true, data: { error: e.message } }));
}
"
